var DynoRemapIndex = class extends Dyno {
	constructor({ from, to, index }) {
		super({
			inTypes: {
				from: "int",
				to: "int",
				index: "int"
			},
			outTypes: { index: "int" },
			inputs: {
				from,
				to,
				index
			},
			statements: ({ inputs, outputs }) => {
				return [`${outputs.index} = ${inputs.index} - ${inputs.from} + ${inputs.to};`];
			}
		});
	}
	dynoOut() {
		return new DynoOutput(this, "index");
	}
};
var PcgNext = class extends Dyno {
	constructor({ state }) {
		const type = valType(state);
		super({
			inTypes: { state: type },
			outTypes: { state: "uint" },
			inputs: { state },
			globals: () => [unindent(`
          uint pcg_next(uint state) {
            return state * 747796405u + 2891336453u;
          }
        `)],
			statements: ({ inputs, outputs }) => {
				const toUint = type === "uint" ? `${inputs.state}` : type === "int" ? `uint(${inputs.state})` : `floatBitsToUint(${inputs.state})`;
				return [`${outputs.state} = pcg_next(${toUint});`];
			}
		});
	}
	dynoOut() {
		return new DynoOutput(this, "state");
	}
};
var PcgHash = class extends Dyno {
	constructor({ state }) {
		super({
			inTypes: { state: "uint" },
			outTypes: { hash: "uint" },
			inputs: { state },
			globals: () => [unindent(`
          uint pcg_hash(uint state) {
            uint hash = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
            return (hash >> 22u) ^ hash;
          }
        `)],
			statements: ({ inputs, outputs }) => [`${outputs.hash} = pcg_hash(${inputs.state});`]
		});
	}
	dynoOut() {
		return new DynoOutput(this, "hash");
	}
};
var PcgMix = class extends Dyno {
	constructor({ value }) {
		const type = valType(value);
		const tempType = sameSizeUvec(type);
		super({
			inTypes: { value: type },
			outTypes: { state: "uint" },
			inputs: { value },
			globals: () => [unindent(`
          uint pcg_mix(uint value) {
            return value;
          }
          uint pcg_mix(uvec2 value) {
            return value.x + 0x9e3779b9u * value.y;
          }
          uint pcg_mix(uvec3 value) {
            return value.x + 0x9e3779b9u * value.y + 0x85ebca6bu * value.z;
          }
          uint pcg_mix(uvec4 value) {
            return value.x + 0x9e3779b9u * value.y + 0x85ebca6bu * value.z + 0xc2b2ae35u * value.w;
          }
        `)],
			statements: ({ inputs, outputs }) => {
				const toUvec = isUintType(type) ? `${inputs.value}` : isIntType(type) ? `${tempType}(${inputs.value})` : `floatBitsToUint(${inputs.value})`;
				return [`${tempType} bits = ${toUvec};`, `${outputs.state} = pcg_mix(bits);`];
			}
		});
	}
	dynoOut() {
		return new DynoOutput(this, "state");
	}
};
var Hash = class extends DynoBlock {
	constructor({ value }) {
		super({
			inTypes: { value: valType(value) },
			outTypes: { hash: "uint" },
			inputs: { value },
			construct: ({ value }) => {
				if (!value) throw new Error("value is required");
				let state = new PcgMix({ value }).outputs.state;
				state = new PcgNext({ state }).outputs.state;
				return new PcgHash({ state }).outputs;
			}
		});
	}
	dynoOut() {
		return new DynoOutput(this, "hash");
	}
};
var Hash2 = class extends DynoBlock {
	constructor({ value }) {
		super({
			inTypes: { value: valType(value) },
			outTypes: { hash: "uvec2" },
			inputs: { value },
			construct: ({ value }) => {
				if (!value) throw new Error("value is required");
				let state = new PcgMix({ value }).outputs.state;
				state = new PcgNext({ state }).outputs.state;
				const x = new PcgHash({ state }).outputs.hash;
				state = new PcgNext({ state }).outputs.state;
				const y = new PcgHash({ state }).outputs.hash;
				return { hash: combine({
					vectorType: "uvec2",
					x,
					y
				}) };
			}
		});
	}
	dynoOut() {
		return new DynoOutput(this, "hash");
	}
};
